def compile_template(signature, diagonal):
    pending = [(signature, 1)]
    polynomial = {}
    while pending:
        word, coefficient = pending.pop()
        position = 0
        while position + 1 < len(word) and word[position] < word[position + 1]:
            position += 1
        if position + 1 >= len(word):
            polynomial[word] = polynomial.get(word, 0) + coefficient
        elif word[position] > word[position + 1]:
            left = word[position]
            right = word[position + 1]
            prefix = word[:position]
            suffix = word[position + 2:]
            pending.append((prefix + (right, left) + suffix, -coefficient))
            if left >= 6 and right < 6 and left - 6 == right:
                pending.append((prefix + suffix, coefficient))
    if not diagonal:
        folded = {}
        for word, coefficient in polynomial.items():
            if coefficient:
                middle = len(word) // 2
                adjoint = tuple(token - 6 for token in word[middle:]) + tuple(token + 6 for token in word[:middle])
                folded[word] = folded.get(word, 0) + coefficient
                folded[adjoint] = folded.get(adjoint, 0) + coefficient
        polynomial = folded
    return [(tuple((1 - token // 6, token % 6) for token in word), coefficient) for word, coefficient in polynomial.items() if coefficient]


def propose(payload):
    words = payload['words']
    adjoints = [tuple((1 - creation, mode) for creation, mode in reversed(word)) for word in words]
    supports = [tuple(sorted(set(mode for creation, mode in word))) for word in words]
    templates = {}
    result = {}
    for i in range(len(words)):
        for j in range(i, len(words)):
            modes = sorted(set(supports[i] + supports[j]))
            ranks = {mode: rank for rank, mode in enumerate(modes)}
            signature = tuple(6 * (1 - creation) + ranks[mode] for creation, mode in adjoints[i] + words[j])
            key = (i == j, signature)
            if key not in templates:
                templates[key] = compile_template(signature, i == j)
            coordinate = (i, j)
            for pattern, coefficient in templates[key]:
                word = tuple((creation, modes[rank]) for creation, rank in pattern)
                result.setdefault(word, {})[coordinate] = coefficient
    return result

def compilegram(pattern):
    terms = {((), ()): 1}
    for creation, mode in pattern:
        following = {}
        for groups, coefficient in terms.items():
            creators, annihilators = groups
            if creation:
                if mode in annihilators:
                    position = annihilators.index(mode)
                    remaining = annihilators[:position] + annihilators[position + 1:]
                    value = coefficient
                    if (len(annihilators) - position - 1) % 2:
                        value = -value
                    key = (creators, remaining)
                    following[key] = following.get(key, 0) + value
                if mode not in creators:
                    position = 0
                    while position < len(creators) and creators[position] < mode:
                        position += 1
                    inserted = creators[:position] + (mode,) + creators[position:]
                    value = coefficient
                    if (len(annihilators) + len(creators) - position) % 2:
                        value = -value
                    key = (inserted, annihilators)
                    following[key] = following.get(key, 0) + value
            else:
                if mode not in annihilators:
                    position = 0
                    while position < len(annihilators) and annihilators[position] < mode:
                        position += 1
                    inserted = annihilators[:position] + (mode,) + annihilators[position:]
                    value = coefficient
                    if (len(annihilators) - position) % 2:
                        value = -value
                    key = (creators, inserted)
                    following[key] = following.get(key, 0) + value
        terms = {key: value for key, value in following.items() if value}
    orbits = {}
    for groups, coefficient in terms.items():
        creators, annihilators = groups
        if creators == annihilators:
            key = groups
            coefficient *= 2
        elif creators < annihilators:
            key = groups
        else:
            key = (annihilators, creators)
        orbits[key] = orbits.get(key, 0) + coefficient
    return tuple((groups[0], groups[1], coefficient) for groups, coefficient in orbits.items() if coefficient)


def propose(payload):
    words = payload['words']
    cache = payload['cache']
    adjoints = [tuple((1 - creation, mode) for creation, mode in reversed(word)) for word in words]
    result = {}
    for i in range(len(words)):
        left = adjoints[i]
        for j in range(i, len(words)):
            labels = {}
            modes = []
            pattern = []
            for creation, mode in left + words[j]:
                label = labels.get(mode, -1)
                if label < 0:
                    label = len(modes)
                    labels[mode] = label
                    modes.append(mode)
                pattern.append((creation, label))
            key = ('symmetricgramorbitsv1', tuple(pattern))
            if key not in cache:
                cache[key] = compilegram(pattern)
            coordinate = (i, j)
            for creators, annihilators, coefficient in cache[key]:
                if i == j:
                    coefficient //= 2
                creationmodes = [modes[label] for label in creators]
                annihilationmodes = [modes[label] for label in annihilators]
                for group in (creationmodes, annihilationmodes):
                    for position in range(len(group)):
                        for previous in range(position):
                            if group[previous] > group[position]:
                                coefficient = -coefficient
                    group.sort()
                if coefficient:
                    word = tuple([(1, mode) for mode in creationmodes] + [(0, mode) for mode in annihilationmodes])
                    result.setdefault(word, {})[coordinate] = coefficient
                    if creators != annihilators:
                        transpose = tuple([(1, mode) for mode in annihilationmodes] + [(0, mode) for mode in creationmodes])
                        result.setdefault(transpose, {})[coordinate] = coefficient
    return result

def reduceword(word, memo):
    cached = memo.get(word)
    if cached is not None:
        return cached
    for k in range(len(word) - 1):
        a = word[k]
        b = word[k + 1]
        if a == b:
            memo[word] = {}
            return memo[word]
        if a > b:
            swapped = word[:k] + (b, a) + word[k + 2:]
            result = {term: -coefficient for term, coefficient in reduceword(swapped, memo).items()}
            if a >= 6 and b < 6 and a - 6 == b:
                contracted = word[:k] + word[k + 2:]
                for term, coefficient in reduceword(contracted, memo).items():
                    result[term] = result.get(term, 0) + coefficient
            result = {term: coefficient for term, coefficient in result.items() if coefficient}
            memo[word] = result
            return result
    result = {word: 1}
    memo[word] = result
    return result


def propose(payload):
    words = payload["words"]
    adjoints = [tuple((1 - flag, mode) for flag, mode in reversed(word)) for word in words]
    memo = {}
    templates = {}
    result = {}
    for i in range(len(words)):
        for j in range(i, len(words)):
            product = adjoints[i] + tuple(words[j])
            modes = sorted(set(mode for flag, mode in product))
            ranks = {mode: rank for rank, mode in enumerate(modes)}
            pattern = tuple(ranks[mode] + 6 * (1 - flag) for flag, mode in product)
            key = (i != j, pattern)
            template = templates.get(key)
            if template is None:
                polynomial = reduceword(pattern, memo)
                if i != j:
                    symmetric = polynomial.copy()
                    for term, coefficient in polynomial.items():
                        half = len(term) // 2
                        partner = tuple(value - 6 for value in term[half:]) + tuple(value + 6 for value in term[:half])
                        symmetric[partner] = symmetric.get(partner, 0) + coefficient
                    polynomial = symmetric
                template = [(tuple((1 if value < 6 else 0, value % 6) for value in term), coefficient) for term, coefficient in polynomial.items() if coefficient]
                templates[key] = template
            coordinate = (i, j)
            for term, coefficient in template:
                concrete = tuple((flag, modes[rank]) for flag, rank in term)
                result.setdefault(concrete, {})[coordinate] = coefficient
    return result

def gramstencil(pattern, symmetric):
    terms = {((), ()): 1}
    for creation, mode in pattern:
        following = {}
        for groups, coefficient in terms.items():
            creators, annihilators = groups
            if creation:
                if mode in annihilators:
                    position = annihilators.index(mode)
                    remaining = annihilators[:position] + annihilators[position + 1:]
                    value = coefficient
                    if (len(annihilators) - position - 1) % 2:
                        value = -value
                    key = (creators, remaining)
                    following[key] = following.get(key, 0) + value
                if mode not in creators:
                    position = 0
                    while position < len(creators) and creators[position] < mode:
                        position += 1
                    inserted = creators[:position] + (mode,) + creators[position:]
                    value = coefficient
                    if (len(annihilators) + len(creators) - position) % 2:
                        value = -value
                    key = (inserted, annihilators)
                    following[key] = following.get(key, 0) + value
            else:
                if mode not in annihilators:
                    position = 0
                    while position < len(annihilators) and annihilators[position] < mode:
                        position += 1
                    inserted = annihilators[:position] + (mode,) + annihilators[position:]
                    value = coefficient
                    if (len(annihilators) - position) % 2:
                        value = -value
                    key = (creators, inserted)
                    following[key] = following.get(key, 0) + value
        terms = {key: value for key, value in following.items() if value}
    if symmetric:
        following = terms.copy()
        for groups, coefficient in terms.items():
            creators, annihilators = groups
            p = len(creators)
            q = len(annihilators)
            if (p * (p - 1) // 2 + q * (q - 1) // 2) % 2:
                coefficient = -coefficient
            key = (annihilators, creators)
            following[key] = following.get(key, 0) + coefficient
        terms = following
    stencil = []
    for groups, coefficient in terms.items():
        if coefficient:
            creators, annihilators = groups
            word = tuple([(1, mode) for mode in creators] + [(0, mode) for mode in annihilators])
            stencil.append((word, coefficient))
    return tuple(stencil)


